// ---- Staker ------------------------------------------------------------

const (
	stakerTxIDAt        = 0
	stakerStartTimeAt   = 32
	stakerEndTimeAt     = 40
	stakerWeightAt      = 48
	stakerNodeIDAt      = 56
	stakerStakeAmountAt = 80
	stakerSize          = 88
)

var _ interface {
	MarshalZAP() ([]byte, error)
	UnmarshalZAP([]byte) error
} = (*Staker)(nil)

// MarshalZAP writes Staker from constant offsets.
func (x *Staker) MarshalZAP() ([]byte, error) {
	if x == nil {
		return nil, nil
	}
	b := zap.NewBuilder(stakerSize + 256)
	ob := b.StartObject(stakerSize)
	ob.SetBytesFixed(stakerTxIDAt, x.TxID[:])
	ob.SetUint64(stakerStartTimeAt, uint64(x.StartTime))
	ob.SetUint64(stakerEndTimeAt, uint64(x.EndTime))
	ob.SetUint64(stakerWeightAt, uint64(x.Weight))
	ob.SetBytesFixed(stakerNodeIDAt, x.NodeID[:])
	if x.StakeAmount != nil {
		ob.SetUint64(stakerStakeAmountAt, uint64((*x.StakeAmount)))
	}
	ob.FinishAsRoot()
	return b.Finish(), nil
}

// UnmarshalZAP reads Staker out of the buffer that arrived.
func (x *Staker) UnmarshalZAP(data []byte) error {
	if x == nil || len(data) == 0 {
		return nil
	}
	m, err := zap.Parse(data)
	if err != nil {
		return fmt.Errorf("Staker: %w", err)
	}
	o := m.Root()
	copy(x.TxID[:], o.BytesFixed(stakerTxIDAt, 32))
	x.StartTime = json.Uint64(o.Uint64(stakerStartTimeAt))
	x.EndTime = json.Uint64(o.Uint64(stakerEndTimeAt))
	x.Weight = json.Uint64(o.Uint64(stakerWeightAt))
	copy(x.NodeID[:], o.BytesFixed(stakerNodeIDAt, 20))
	if v := json.Uint64(o.Uint64(stakerStakeAmountAt)); v != json.Uint64(0) {
		x.StakeAmount = &v
	}
	return nil
}

