const (
	uTXOLocktimeAt = 0
	uTXOAmountAt   = 8
	uTXOAddressAt  = 16
	uTXOMessageAt  = 24
	uTXOSize       = 32
)

var _ interface {
	MarshalZAP() ([]byte, error)
	UnmarshalZAP([]byte) error
} = (*UTXO)(nil)

// MarshalZAP writes UTXO from constant offsets.
func (x *UTXO) MarshalZAP() ([]byte, error) {
	if x == nil {
		return nil, nil
	}
	b := zap.NewBuilder(uTXOSize + 256)
	ob := b.StartObject(uTXOSize)
	ob.SetUint64(uTXOLocktimeAt, uint64(x.Locktime))
	ob.SetUint64(uTXOAmountAt, uint64(x.Amount))
	ob.SetText(uTXOAddressAt, string(x.Address))
	ob.SetText(uTXOMessageAt, string(x.Message))
	ob.FinishAsRoot()
	return b.Finish(), nil
}

// UnmarshalZAP reads UTXO out of the buffer that arrived.
func (x *UTXO) UnmarshalZAP(data []byte) error {
	if x == nil || len(data) == 0 {
		return nil
	}
	m, err := zap.Parse(data)
	if err != nil {
		return fmt.Errorf("UTXO: %w", err)
	}
	o := m.Root()
	x.Locktime = json.Uint64(o.Uint64(uTXOLocktimeAt))
	x.Amount = json.Uint64(o.Uint64(uTXOAmountAt))
	x.Address = string(strings.Clone(o.Text(uTXOAddressAt)))
	x.Message = string(strings.Clone(o.Text(uTXOMessageAt)))
	return nil
}
